import "./css/Festval_CardItem.css";


const Festval_card_item = ({cardItem}) => {

  const {title, eventstartdate, eventenddate, addr1, addr2, firstimage , mapx, mapy,tel} = cardItem;

  const startyear = eventstartdate.split(3);
  const startmonth = eventstartdate.split(3,5);
  const startday = eventstartdate.split(5,7);

  console.log("   startY" + startyear);
  console.log("   startM" + startmonth);
  console.log("   startD" + startday);
  
    return(
        <div className='cardList_item'>            

            <img className='itemImage' src={firstimage} alt="com" />
            <ul className="itemInfo">
              <li className="itemAlram">
                  <span>준비중</span>
              </li>              
              <li className="itemTitle">
                  {title}
              </li>                
              <li className="itemDate">
                <span className="sub">기간</span>                  
                <span>{eventstartdate}</span>~<span>{eventenddate}</span>                  
              </li>
              <li className="itemAddress">
                <span className="sub">장소</span>                  
                <span>{addr1} {addr2}</span>                  
              </li>
              <li className="itemLink">
                <a className="itemMap" href="#">{mapx}<br />{mapy}</a>
                <a className="itemHome" href="#">{tel}</a>
              </li>
            </ul>              
            
        </div>
    );
};

export default Festval_card_item;
